/**
 * Returns the count percent of total
 *
 * @param {number} count how many out of total amount
 * @param {number} total total amount
 * @param {number} roundTo number of decimal places to round to (if not passed, returns no decimals)
 * @param {boolean} [forceDecimal=false] whether to force full decimal points even if 0's
 * @param {boolean} [asNumber=false] whether to return the percentage value as a number instead of a string (disregards the forceDecimal prop when a zero (0) is returned)

 * @returns {string} percent - The toString version of percent.
 */
export function getPercent(
  count = 0,
  total = 100,
  roundTo = 0,
  forceDecimal = false,
  asNumber = false,
) {
  if (total === 0) {
    if (asNumber) {
      return 0;
    }

    if (roundTo <= 0) {
      return '--';
    }

    return [...Array(roundTo).keys()].reduce((dashes) => `${dashes}-`, '-.');
  }

  const fixedPercentage = ((count / total) * 100).toFixed(roundTo);

  if (asNumber) {
    return parseFloat(fixedPercentage);
  }

  // If !forceDecimal, we parseFloat to change 100.00% -> 100% and 55.10% -> 55.1%
  return `${forceDecimal ? fixedPercentage : parseFloat(fixedPercentage)}%`;
}
